    double   m0_0;
    double   c20_0;
    double   c30_0;
    double   dx0_0;
    lambda20_0=0;
    x10_0 = log10Guarded(Re10_0,"Re1");
    y10_0 = log10Guarded(64*Re10_0,"64*Re1");
